import type { ReactNode } from 'react';
import { Link } from 'react-router';
import { ArrowUpRight } from 'lucide-react';

type Cta = { label: string; href: string; variant?: 'dark' | 'outline' | 'mint' };

/**
 * Compact page header for the inner pages. Keeps the brand's eyebrow + coordinate
 * rhythm and the mint "click" period, without the home hero's full-bleed scale.
 */
export function PageHero({
	eyebrow,
	title,
	intro,
	ctas,
}: {
	eyebrow: string;
	title: ReactNode;
	intro: string;
	ctas?: Cta[];
}) {
	return (
		<section className="page-hero section-rail" aria-labelledby="page-hero-heading">
			<div className="page-hero-top">
				<span className="eyebrow">
					<span className="status-dot" /> {eyebrow}
				</span>
				<span className="hero-coordinate">LATINOAMÉRICA ↗</span>
			</div>
			<h1 id="page-hero-heading" className="page-title">
				{title}
			</h1>
			<div className="page-hero-bottom">
				<p className="page-hero-intro">{intro}</p>
				{ctas && ctas.length > 0 && (
					<div className="page-hero-ctas">
						{ctas.map(cta => (
							<Link
								key={cta.href}
								className={`button button-${cta.variant ?? 'dark'}`}
								to={cta.href}
							>
								{cta.label} <ArrowUpRight size={20} />
							</Link>
						))}
					</div>
				)}
			</div>
		</section>
	);
}

